    let x = @gpu_alloc([1024]f32);
    for i in @gpu_parallel(0, 1024) {
        x(i) = @itof(i);
    }
    @gpu_sync();
    0
}
EOF

impala --emit-hip hello_mi355x.impala
hipcc -o hello hello_mi355x.cpp
