pub const ContentAddressableStorage = struct {
    blocks: AutoHashMap(u64, MemoryBlock),
    hash_to_id: AutoHashMap([32]u8, u64),
    lru_order: ArrayList(u64),
    next_id: u64,
    total_size: usize,
    max_size: usize,
    mutex: Mutex,
    allocator: Allocator,

    pub fn init(allocator: Allocator, max_size: usize) ContentAddressableStorage {
        return .{
            .blocks = AutoHashMap(u64, MemoryBlock).init(allocator),
            .hash_to_id = AutoHashMap([32]u8, u64).init(allocator),
            .lru_order = ArrayList(u64).init(allocator),
            .next_id = 1,
            .total_size = 0,
            .max_size = max_size,
            .mutex = Mutex{},
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *ContentAddressableStorage) void {
        self.mutex.lock();
        defer self.mutex.unlock();

        var it = self.blocks.iterator();
        while (it.next()) |entry| {
            var block = entry.value_ptr;
            block.deinit();
        }

        self.blocks.deinit();
        self.hash_to_id.deinit();
        self.lru_order.deinit();
    }

    pub fn store(self: *ContentAddressableStorage, data: []const u8) !u64 {
        self.mutex.lock();
        defer self.mutex.unlock();

        var hash: [32]u8 = undefined;
        std.crypto.hash.blake3.hash(data, &hash, .{});

        if (self.hash_to_id.get(hash)) |existing_id| {
            if (self.blocks.getPtr(existing_id)) |block| {
                block.ref_count += 1;
                block.access_count += 1;
                block.last_access = std.time.milliTimestamp();
                try self.updateLRU(existing_id);
                return existing_id;
            }
        }

        while (self.total_size + data.len > self.max_size) {
            try self.evictLRU();
        }

        const id = self.next_id;
        self.next_id += 1;

        var block = try MemoryBlock.init(self.allocator, id, data);
        try self.blocks.put(id, block);
        try self.hash_to_id.put(hash, id);
        try self.lru_order.append(id);
        self.total_size += data.len;

        return id;
    }

    pub fn retrieve(self: *ContentAddressableStorage, id: u64) ?[]const u8 {
        self.mutex.lock();
        defer self.mutex.unlock();

        if (self.blocks.getPtr(id)) |block| {
            block.access_count += 1;
            block.last_access = std.time.milliTimestamp();
            self.updateLRU(id) catch {};
            return block.data;
        }
        return null;
    }

    fn updateLRU(self: *ContentAddressableStorage, id: u64) !void {
        var i: usize = 0;
        while (i < self.lru_order.items.len) {
            if (self.lru_order.items[i] == id) {
                _ = self.lru_order.orderedRemove(i);
                break;
            }
            i += 1;
        }
        try self.lru_order.append(id);
    }

    fn evictLRU(self: *ContentAddressableStorage) !void {
        if (self.lru_order.items.len == 0) return;

        const id = self.lru_order.orderedRemove(0);
        if (self.blocks.fetchRemove(id)) |kv| {
            var block = kv.value;
            _ = self.hash_to_id.remove(block.content_hash);
            self.total_size -= block.size;
            block.deinit();
        }
    }
};

