    pub fn scheduleToCore(self: *DynamicTaskScheduler, cores: []ProcessingCore, analyzer: *DataFlowAnalyzer) !?u64 {
        if (self.task_queue.items.len == 0) return null;

        var best_idx: usize = 0;
        var best_priority: u32 = self.task_queue.items[0].priority;

        for (self.task_queue.items, 0..) |task, i| {
            if (task.priority > best_priority) {
                best_priority = task.priority;
                best_idx = i;
            }
        }

        const task = self.task_queue.orderedRemove(best_idx);
        _ = self.task_map.remove(task.id);

        var best_core_idx: usize = 0;
        var min_load: f32 = cores[0].load;

        for (cores, 0..) |core, i| {
            if (core.load < min_load) {
                min_load = core.load;
                best_core_idx = i;
            }
        }

        cores[best_core_idx].load += task.computation_weight;
        try cores[best_core_idx].processing_queue.append(task.id);

        return task.id;
    }
